head.script:
scwin.labelFormatter = function(itemArr) { //debugger;
    var customArr = itemArr;
    for (var i = 0; i < itemArr.length; i++) {
        customArr[i].label = itemArr[i].label + " label change";
    }
    return customArr;
}
scwin.selectbox1_onviewchange = function(info) {
    console.log("oldValue#####" + info.oldValue + "newValue#####" + info.newValue);
};
scwin.selectbox1_onchange = function() {
    console.log("onchange");
};
scwin.trigger1_onclick = function(e) {};
scwin.unitTest = function() {
    //init
    // WebSquare.wUnit.start();
    //Test step 1. 샘플 실행 후 selectbox의 data를 확인한다.
    //1. After running the sample, check the data of the selectbox.
    //Verify step 1. The 'label change' value is added to the basic selectbox data (# 1).
    //WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('selectbox1_label').textContent == '1번 label change'", "true");
    //for mobile
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('selectbox1').getText() == '1번 label change'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    //Function 
    //Created by: Thuyet.Pham
    //Created date: 23-Feb-2018
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
